INSERT INTO `categories` VALUES (1,4,' Appetizer','Voorgerechten','','','Active'),(2,4,'Naan','Naan','Indian bread prepared in the tandoor','Indiaas brood, bereid in de tandoor','Active'),(3,4,'Special menu\'s','Special menu\'s','','','Active'),(4,4,'Tandoori specialties','Tandoori specialiteiten','The tandoor is an Indian charcoal clay oven in which specially marinated dishes are roasted, served with Basmati rice or nan, lentils and paperdam','De tandoor is een Indiaase houtskool klei-oven waar speciaal gemarineerde gerechten in worden geroosterd, geserveerd met Basmati rijst of nan, linzen en paperdam','Active'),(5,4,' Curry dishes','Curry gerechten','Served with basmati rice, vegetables and paperdam','Geserveerd met basmati rijst, groenten en paperdam','Active'),(6,4,'Vegetarian side dishes','Vegetarische bijgerechten','Side dish or as main course with basmati rice and paperdam','Bijgerecht of als hoofdgerecht met basmati rijst en paperdam','Active'),(7,4,'Desserts','Desserts','Side dish or as main course with basmati rice and paperdam','Bijgerecht of als hoofdgerecht met basmati rijst en paperdam','Active'),(8,4,'Drinks','Dranken','','','Active'),(9,4,'Biryani dishes','Biryani gerechten','A main course in which rice, meat and / or vegetables, raisins, almonds and herbs are made into a tasty dish. Biryani is served with lentils and raita','Een hoofdgerecht waarbij rijst, vlees en/of groenten, rozijnen, amandelen en kruiden tot een smakelijk gerecht zijn gemaakt. Biryani wordt geserveerd met linzen en raita','Active'),(10,4,'Extras','Extra\'s','','','Active'),(11,4,' Party menus','Party menu\'s','voor 10-50 persons','voor 10-50 personen','Active'),(15,5,'Rice Table','Rijsttafel','','','Active'),(16,5,'Fish / Shrimp dishes','Vis / Garnalen gerechten','All dishes are served with white rice, prawn crackers, atjar, serundeng and sambal','Alle gerechten worden geserveerd met witte rijst, kroepoek, atjar, serundeng en sambal\n\n','Active'),(17,5,'Chicken dishes','├é┬áKip gerechten','All dishes are served with white rice, prawn crackers, atjar, serundeng and sambal','Alle gerechten worden geserveerd met witte rijst, kroepoek, atjar, serundeng en sambal\n','Active'),(18,5,'Rames gerechten','Rames dishes','','','Active'),(19,5,'Lamb dishes','Lams gerechten','All dishes are served with white rice, prawn crackers, atjar, serundeng and sambal','Alle gerechten worden geserveerd met witte rijst, kroepoek, atjar, serundeng en sambal\n','Active'),(20,5,'Vegetable / vegetarian dishes','Groente / Vegetarische gerechten','All dishes are served with white rice, prawn crackers, atjar, serundeng and sambal','Alle gerechten worden geserveerd met witte rijst, kroepoek, atjar, serundeng en sambal','Active'),(21,5,'Indo Desserts','Indo Nagerechten','','','Active'),(22,5,'Appetizer','Voorgerechten','','','Active'),(23,5,'Indo Bijgerechten','Indo Side Dishes','','','Active'),(30,7,' soft drinks, juices, coffee, tea','frisdranken,sappen,koffie,thee','','','Active'),(31,7,' beer, wine','bier,wijn','','','Active'),(50,4,'Vegetarian Menu','Vegetarian Menu','','','Active'),(51,4,'Tandoori & Curry Menu','Tandoori & Curry Menu','','','Active'),(52,4,'Indonesian (MENU)','Indonesia (MENU)','','','Active'),(53,4,'Vegetarian Main Dishes ','Vegetarische Hoofdgerechten','','','Active'),(54,0,'Vegan MENU','Vegan MENU','','','Active');
